/* ClearSight V2.8 · Access policy and escalation design reference.
 * This model demonstrates decisions and audit receipts in local state. The server
 * must enforce tenancy, authorization, identity, version checks and scheduling.
 */
'use strict';
const GV_MODULES=[['programs','Programs & requirements'],['kri','KRIs & branch returns'],['risks','Risks, RCSA & losses'],['documents','Documents & evidence'],['vendors','Vendors & privacy'],['reports','Reports & board packs'],['access','Access administration'],['escalation','Escalation policies']];
const GV_ACTIONS=[['view','View'],['edit','Create / edit'],['submit','Submit'],['approve','Approve'],['export','Export'],['manage','Manage']];
const GV_TRIGGERS=[['kri-breach','KRI threshold breached'],['quality-defect','Quality defect detected'],['document-expired','Document expired'],['deadline-approaching','Deadline approaching'],['deadline-passed','Deadline passed'],['approval-overdue','Approval overdue']];
const GV_SEVERITIES=['Any','Low','Medium','High','Critical'];
const gvState=()=>S.accessControl;
const gvRole=id=>gvState().roles.find(x=>x.id===id);
const gvPerson=id=>REC_PEOPLE.find(x=>x.id===id);
const gvScope=id=>id?orgName(id):'Whole organization';
const gvToday=()=>S.asOf;
const gvClock=()=>new Date().toISOString();
const gvActive=(x,on=gvToday())=>x.status==='Active'&&(!x.starts||x.starts<=on)&&(!x.ends||x.ends>=on);
const gvCovers=(root,target,desc=true)=>root===''||root===target||(desc&&!!target&&orgWithin(target,root));
const gvOverlap=(a,b)=>gvCovers(a,b)||gvCovers(b,a);
const gvRule=(mods,acts,effect='allow')=>Object.fromEntries(mods.flatMap(m=>acts.map(a=>[m+'.'+a,effect])));
const gvAudit=(action,ref,detail)=>{const row={id:uid('GVA'),action,ref,detail,by:typeof recActor==='function'?recActor().name:'Demo operator',at:gvClock()};gvState().audit.unshift(row);audit(action,ref,row.by);};
function gvInit(){
 if(S.accessControl?.version===1)return;
 const all=GV_MODULES.map(x=>x[0]), operational=['programs','kri','risks','documents','vendors'];
 S.accessControl={version:1,roles:[
  {id:'ROLE-ADMIN',name:'Workspace administrator',description:'Manages workspace access and escalation configuration. Operational approvals remain independently assigned.',system:true,status:'Active',scopeRoot:'',descendants:true,permissions:{...gvRule(all,['view']),...gvRule(['access','escalation'],['edit','manage','export'])},reviewEvery:90,updated:gvToday()},
  {id:'ROLE-CONTRIBUTOR',name:'Branch risk contributor',description:'Captures branch returns and supporting records. Cannot approve their own or another person’s returns.',system:false,status:'Active',scopeRoot:'',descendants:true,permissions:{...gvRule(operational,['view','edit','submit']),...gvRule(operational,['approve'],'deny')},reviewEvery:90,updated:gvToday()},
  {id:'ROLE-REVIEWER',name:'Independent risk reviewer',description:'Challenges and approves submitted records within the assigned location; no preparation permissions.',system:false,status:'Active',scopeRoot:'',descendants:true,permissions:{...gvRule(operational,['view','approve']),...gvRule(['reports'],['view','export']),...gvRule(['kri'],['edit','submit'],'deny')},reviewEvery:90,updated:gvToday()},
  {id:'ROLE-CRO',name:'Chief risk officer',description:'Reviews risk decisions and management reporting across assigned locations.',system:false,status:'Active',scopeRoot:'',descendants:true,permissions:{...gvRule(all.filter(x=>!['access'].includes(x)),['view']),...gvRule(['risks','reports'],['approve','export']),...gvRule(['escalation'],['manage'])},reviewEvery:90,updated:gvToday()},
  {id:'ROLE-BOARD',name:'Board observer',description:'Read access to management reporting; no ability to alter underlying evidence or approvals.',system:false,status:'Active',scopeRoot:'',descendants:true,permissions:gvRule(['reports'],['view','export']),reviewEvery:90,updated:gvToday()},
  {id:'ROLE-AUDITOR',name:'Internal audit',description:'Inspects records and extracts evidence without changing records or approvals.',system:false,status:'Active',scopeRoot:'',descendants:true,permissions:gvRule(all,['view','export']),reviewEvery:90,updated:gvToday()}
 ],assignments:[
  {id:'GVA-01',userId:'USR-05',roleId:'ROLE-ADMIN',scopeId:'',starts:'2026-01-01',ends:'',status:'Active',reviewDue:'2026-12-31',reason:'Workspace administration',reviewed:'2026-10-01'},
  {id:'GVA-02',userId:'USR-01',roleId:'ROLE-CONTRIBUTOR',scopeId:'B-IK',starts:'2026-01-01',ends:'',status:'Active',reviewDue:'2026-11-10',reason:'Ikeja branch reporting',reviewed:'2026-08-10'},
  {id:'GVA-03',userId:'USR-04',roleId:'ROLE-CONTRIBUTOR',scopeId:'B-EN',starts:'2026-01-01',ends:'',status:'Active',reviewDue:'2026-12-10',reason:'Enugu branch reporting',reviewed:'2026-09-10'},
  {id:'GVA-04',userId:'USR-03',roleId:'ROLE-REVIEWER',scopeId:'',starts:'2026-01-01',ends:'',status:'Active',reviewDue:'2026-12-01',reason:'Second-line independent review',reviewed:'2026-09-01'},
  {id:'GVA-05',userId:'USR-02',roleId:'ROLE-CRO',scopeId:'',starts:'2026-01-01',ends:'',status:'Active',reviewDue:'2026-12-01',reason:'Executive risk accountability',reviewed:'2026-09-01'},
  {id:'GVA-06',userId:'USR-04',roleId:'ROLE-AUDITOR',scopeId:'U-EN-REC',starts:'2026-10-01',ends:'2026-11-10',status:'Active',reviewDue:'2026-11-10',reason:'Time-limited evidence review',reviewed:'2026-10-01'}
 ],directRules:[{id:'GVD-01',userId:'USR-01',permission:'documents.export',effect:'deny',scopeId:'B-IK',starts:'2026-10-01',ends:'2026-12-31',status:'Active',reason:'Restrict raw document extraction during access review',approvedBy:'USR-05'}],audit:[],policies:[
  {id:'ESC-KRI',name:'Material KRI breach',trigger:'kri-breach',severity:'High',scopeId:'',status:'Active',clock:'calendar',stop:'resolved',owner:'USR-02',repeat:'One notice per level',version:1,levels:[{after:0,target:'owner',fallback:'ROLE-REVIEWER'},{after:4,target:'ROLE-REVIEWER',fallback:'ROLE-CRO'},{after:24,target:'ROLE-CRO',fallback:'ROLE-ADMIN'}]},
  {id:'ESC-QUALITY',name:'Document review quality defect',trigger:'quality-defect',severity:'Any',scopeId:'',status:'Active',clock:'business',stop:'acknowledged',owner:'USR-03',repeat:'One notice per level',version:1,levels:[{after:0,target:'owner',fallback:'ROLE-REVIEWER'},{after:8,target:'ROLE-REVIEWER',fallback:'ROLE-CRO'},{after:16,target:'ROLE-CRO',fallback:'ROLE-ADMIN'}]},
  {id:'ESC-EXPIRY',name:'Expired document',trigger:'document-expired',severity:'Any',scopeId:'',status:'Active',clock:'business',stop:'resolved',owner:'USR-03',repeat:'One notice per level',version:1,levels:[{after:0,target:'owner',fallback:'ROLE-REVIEWER'},{after:8,target:'ROLE-REVIEWER',fallback:'ROLE-CRO'},{after:24,target:'ROLE-CRO',fallback:'ROLE-ADMIN'}]},
  {id:'ESC-DEADLINE',name:'Missed program deadline',trigger:'deadline-passed',severity:'Any',scopeId:'',status:'Active',clock:'business',stop:'resolved',owner:'USR-03',repeat:'One notice per level',version:1,levels:[{after:0,target:'owner',fallback:'ROLE-REVIEWER'},{after:8,target:'ROLE-REVIEWER',fallback:'ROLE-CRO'},{after:24,target:'ROLE-CRO',fallback:'ROLE-ADMIN'}]}
 ],draftRole:null,draftPolicy:null,simulator:{policyId:'ESC-KRI',scopeId:'U-IK-PAY',ownerId:'USR-01',at:gvToday()+'T16:00',ackAfter:'',resolvedAfter:'',severity:'High'},simulation:null};
 save();
}
function gvNav(active){return `<nav class="gv-nav" aria-label="Access and escalation navigation">${[['Roles & permissions','roles'],['People & access review','access-review'],['Escalation matrix','escalation-matrix']].map(([t,r])=>link(t,r,active===r?'primary small':'small')).join('')}</nav>`;}
function gvScopeOptions(selected='',allowAll=true){return `${allowAll?`<option value="" ${!selected?'selected':''}>Whole organization</option>`:''}${ORG.map(n=>`<option value="${n.id}" ${selected===n.id?'selected':''}>${e(orgName(n.id))}</option>`).join('')}`;}
function gvPeopleOptions(selected='',none=false){return `${none?'<option value="">Unassigned</option>':''}${REC_PEOPLE.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${e(p.name)}</option>`).join('')}`;}
function gvRoleOptions(selected='',includeOwner=false){return `${includeOwner?`<option value="owner" ${selected==='owner'?'selected':''}>Record owner</option>`:''}${gvState().roles.filter(r=>r.status==='Active').map(r=>`<option value="${r.id}" ${selected===r.id?'selected':''}>${e(r.name)}</option>`).join('')}`;}
function gvChecks(role,permissions=role.permissions){
 const issues=[];
 for(const [m,label] of GV_MODULES){if(permissions[m+'.approve']==='allow'&&(permissions[m+'.edit']==='allow'||permissions[m+'.submit']==='allow'))issues.push(label+': preparation and approval are combined.');}
 return issues;
}
function gvDecision(userId,permission,scopeId,on=gvToday(),context={}){
 gvInit();const trace=[];if(!gvPerson(userId)||(!orgNode(scopeId)&&scopeId!==''))return {allowed:false,reason:'Unknown person or location.',trace};
 const matching=gvState().assignments.filter(a=>a.userId===userId&&gvActive(a,on)&&gvCovers(a.scopeId,scopeId));
 for(const a of matching){const r=gvRole(a.roleId);if(!r||r.status!=='Active'||!gvCovers(r.scopeRoot,scopeId,r.descendants))continue;const effect=r.permissions[permission]||'unset';trace.push({source:r.name,assignment:a.id,effect,scope:gvScope(a.scopeId),until:a.ends||'No end date'});}
 for(const d of gvState().directRules.filter(d=>d.userId===userId&&d.permission===permission&&gvActive(d,on)&&gvCovers(d.scopeId,scopeId)))trace.push({source:'Direct rule: '+d.reason,assignment:d.id,effect:d.effect,scope:gvScope(d.scopeId),until:d.ends||'No end date'});
 if(context.makerId===userId&&permission.endsWith('.approve'))return {allowed:false,reason:'Separation of duties: a person cannot approve their own submission.',trace};
 if(trace.some(t=>t.effect==='deny'))return {allowed:false,reason:'An explicit deny overrides all grants within this scope.',trace};
 if(trace.some(t=>t.effect==='allow'))return {allowed:true,reason:'An active grant covers this action and location.',trace};
 return {allowed:false,reason:'No active grant covers this action and location. Unset is not permission.',trace};
}
function gvRoleCount(id){return gvState().assignments.filter(a=>a.roleId===id&&gvActive(a)).length;}
function gvRolesView(){gvInit();const roles=gvState().roles,active=gvState().assignments.filter(a=>gvActive(a));return header('Roles & permissions','Define who can see, prepare, approve and export information. Scope and independent approval remain explicit.',btn(icon('plus')+' Create role','gv-new-role','','primary'),'Workspace administration')+gvNav('roles')+metricRow([metric('Active roles',roles.filter(r=>r.status==='Active').length,'Reusable permission policies','shield'),metric('Assigned people',new Set(active.map(a=>a.userId)).size,REC_PEOPLE.length+' people in this demonstration','users'),metric('Reviews overdue',gvState().assignments.filter(a=>gvActive(a)&&a.reviewDue<gvToday()).length,'Review with an accountable owner','clock'),metric('Explicit restrictions',gvState().directRules.filter(d=>gvActive(d)&&d.effect==='deny').length,'Deny takes precedence over grants','lock')])+`<div class="gv-role-grid">${roles.map(r=>`<article class="panel gv-role-card"><div class="row between"><span class="gv-role-icon">${icon(r.system?'settings':r.id==='ROLE-BOARD'?'eye':'shield')}</span>${pill(r.system?'Protected system role':r.status,r.system?'blue':r.status==='Active'?'green':'')}</div><h2>${e(r.name)}</h2><p>${e(r.description)}</p><div class="gv-role-meta"><span><strong>${Object.values(r.permissions).filter(v=>v==='allow').length}</strong> allowed actions</span><span><strong>${gvRoleCount(r.id)}</strong> active assignments</span></div><small class="muted">Maximum scope: ${e(gvScope(r.scopeRoot))}</small><div class="gv-card-actions">${link('Review permissions','role-detail?id='+r.id,'small')}${btn('Duplicate','gv-clone-role',`data-id="${r.id}"`,'quiet small')}</div></article>`).join('')}</div>`+notice('Policy preview uses the demonstration date '+date(gvToday())+'. Identity and access enforcement must run on the application server.','mini');}
function gvDraftRole(id){const st=gvState();if(st.draftRole&&st.draftRole.sourceId===id)return st.draftRole;const r=gvRole(id);if(!r)return null;st.draftRole={...clone(r),sourceId:id,newRole:false,reason:''};save();return st.draftRole;}
function gvPermissionMatrix(r,readonly=false){return `<div class="gv-matrix-wrap" tabindex="0" aria-label="Permission matrix; scroll horizontally on narrow screens"><table class="gv-matrix"><thead><tr><th scope="col">Module</th>${GV_ACTIONS.map(a=>`<th scope="col">${a[1]}</th>`).join('')}</tr></thead><tbody>${GV_MODULES.map(([m,label])=>`<tr><th scope="row">${e(label)}</th>${GV_ACTIONS.map(([a,title])=>{const val=r.permissions[m+'.'+a]||'unset';return `<td><select class="gv-effect gv-effect-${val}" aria-label="${e(label+' — '+title)}" data-gv-permission="${m}.${a}" ${readonly?'disabled':''}>${[['unset','— Unset'],['allow','Allow'],['deny','Deny']].map(([v,t])=>`<option value="${v}" ${v===val?'selected':''}>${t}</option>`).join('')}</select></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
function gvRoleDetail(){gvInit();const id=current.params.get('id'),r=id==='new'?gvState().draftRole:gvDraftRole(id);if(!r||r.sourceId!==id)return header('Role not found','Choose a known role from the role catalogue.',link('Roles & permissions','roles'));const original=gvRole(id),readonly=!!r.system;return header(e(r.name||'New role'),'Changes remain in this draft until you save. Existing assignments retain their selected organization scope.',link('Back to roles','roles')+(readonly?btn('Duplicate to customize','gv-clone-role',`data-id="${id}"`,'primary'):btn('Save role','gv-save-role','','primary')),'Role configuration')+gvNav('roles')+(readonly?notice('This system role is protected. Duplicate it for a custom role; keep at least one active organization-wide administrator.'):notice('<strong>Decision order:</strong> scope and dates → explicit deny → grant → default deny. Approval of your own submission is always denied.','mini'))+`<div id="gv-role-error" class="form-error" role="alert"></div><section class="panel pad mb16"><div class="field-grid"><label>Role name<input maxlength="80" data-gv-role="name" value="${e(r.name)}" ${readonly?'disabled':''}></label><label>Status<select data-gv-role="status" ${readonly?'disabled':''}>${['Active','Inactive'].map(v=>`<option ${v===r.status?'selected':''}>${v}</option>`).join('')}</select></label><label class="full">Purpose<textarea data-gv-role="description" ${readonly?'disabled':''}>${e(r.description)}</textarea></label><label>Maximum organizational scope<select data-gv-role="scopeRoot" ${readonly?'disabled':''}>${gvScopeOptions(r.scopeRoot)}</select></label><label>Access review interval (days)<input type="number" min="1" max="365" data-gv-role="reviewEvery" value="${r.reviewEvery}" ${readonly?'disabled':''}></label><label class="checkbox-row full"><input type="checkbox" data-gv-role="descendants" ${r.descendants?'checked':''} ${readonly?'disabled':''}>Include child departments and units within the selected maximum scope</label></div></section>`+panel('Permission matrix','Allow grants the action. Deny overrides grants from other roles. Unset grants nothing.',gvPermissionMatrix(r,readonly))+`<section class="panel pad mt16"><h2>Independent preparation and approval</h2><p>Each custom role keeps preparation and approval separate for the same module. Overlapping assignments are checked again when access is granted.</p><div id="gv-sod-preview">${gvSodMarkup(r)}</div>${!readonly?`<label>Reason for this change<textarea data-gv-role="reason" placeholder="Explain the business need, access boundary and review owner.">${e(r.reason||'')}</textarea></label><div class="gv-card-actions">${btn('Discard changes','gv-discard-role','','quiet')}${btn('Save role','gv-save-role','','primary')}</div>`:''}</section>`+(original?panel('Current assignments','Role changes affect these assignments after validation.',gvAssignmentsTable(gvState().assignments.filter(a=>a.roleId===id),false)):'');}
function gvSodMarkup(r){const issues=gvChecks(r);return issues.length?`<div class="gv-conflicts" role="status"><strong>Resolve before saving</strong><ul>${issues.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div>`:`<div class="gv-ok">${icon('check')} Preparation and approval are separated in this role.</div>`;}
function gvConflictFor(assignment,roles=gvState().roles,assignments=gvState().assignments){
 if(assignment.status!=='Active'||(assignment.ends&&assignment.ends<gvToday()))return [];
 const r=roles.find(r=>r.id===assignment.roleId);if(!r||r.status!=='Active')return [];
 const own=gvChecks(r);const overlaps=assignments.filter(a=>a.id!==assignment.id&&a.userId===assignment.userId&&a.status==='Active'&&(!a.ends||a.ends>=gvToday())&&(!a.ends||a.ends>=assignment.starts)&&(!assignment.ends||assignment.ends>=a.starts)&&gvOverlap(a.scopeId,assignment.scopeId));
 for(const a of overlaps){const other=roles.find(r=>r.id===a.roleId);if(!other||other.status!=='Active')continue;for(const [m,label] of GV_MODULES){const permission=(act)=>r.permissions[m+'.'+act]==='allow',otherPermission=(act)=>other.permissions[m+'.'+act]==='allow';if((permission('approve')&&(otherPermission('edit')||otherPermission('submit')))||(otherPermission('approve')&&(permission('edit')||permission('submit'))))own.push(label+': overlaps '+other.name+' within '+gvScope(a.scopeId)+'.');}}
 return [...new Set(own)];
}
function gvSaveRole(){const d=gvState().draftRole;requireValue(d&&!d.system,'Protected system roles cannot be edited.');requireValue(d.name.trim().length>=3,'Enter a meaningful role name.');requireValue(d.description.trim().length>=12,'Describe the purpose of this role.');requireValue(d.reason.trim().length>=12,'Give a reason for the access change.');requireValue(!gvState().roles.some(r=>r.id!==d.sourceId&&r.name.toLowerCase()===d.name.trim().toLowerCase()),'A role with this name already exists.');requireValue(d.scopeRoot===''||orgNode(d.scopeRoot),'Choose a valid maximum scope.');bounded(d.reviewEvery,1,365,'Access review interval');const issues=gvChecks(d);requireValue(!issues.length,issues.join(' '));const next={...clone(d),id:d.newRole?uid('ROLE'):d.sourceId,name:d.name.trim(),reviewEvery:Number(d.reviewEvery),updated:gvToday()};delete next.sourceId;delete next.newRole;delete next.reason;const roles=gvState().roles.filter(r=>r.id!==next.id).concat([next]);const assigned=gvState().assignments.filter(a=>a.roleId===next.id&&a.status==='Active'&&(!a.ends||a.ends>=gvToday()));for(const a of assigned){requireValue(gvCovers(next.scopeRoot,a.scopeId,next.descendants),'This maximum scope would exclude '+gvPerson(a.userId).name+'’s existing assignment. Change that assignment first.');requireValue(!gvConflictFor(a,roles).length,'Role change creates a preparation / approval conflict for '+gvPerson(a.userId).name+'.');}const idx=gvState().roles.findIndex(r=>r.id===next.id);if(idx>=0)gvState().roles[idx]=next;else gvState().roles.push(next);gvState().draftRole=null;gvAudit((idx>=0?'Updated':'Created')+' role',next.id,d.reason);go('role-detail?id='+next.id);toast('Role saved; scope and separation of duties checked.');}
function gvNewRole(sourceId){const source=sourceId&&gvRole(sourceId);gvState().draftRole={...(source?clone(source):{name:'',description:'',permissions:{},scopeRoot:'',descendants:true,reviewEvery:90,status:'Active'}),id:'new',name:source?source.name+' (copy)':'',sourceId:'new',newRole:true,system:false,reason:''};save();go('role-detail?id=new');}
function gvAssignmentStatus(a){if(a.status!=='Active')return a.status;if(a.starts>gvToday())return 'Scheduled';if(a.ends&&a.ends<gvToday())return 'Expired';if(a.reviewDue<gvToday())return 'Review overdue';return 'Active';}
function gvAssignmentsTable(rows,actionable=true){return rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Person / role</th><th>Location</th><th>Validity</th><th>Access review</th>${actionable?'<th>Actions</th>':''}</tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${e(gvPerson(a.userId)?.name||'Unknown person')}</strong><small>${e(gvRole(a.roleId)?.name||'Unknown role')}</small></td><td data-label="Location">${e(gvScope(a.scopeId))}</td><td data-label="Validity">${pill(gvAssignmentStatus(a),gvAssignmentStatus(a)==='Review overdue'?'amber':'')}<small>${date(a.starts)} → ${a.ends?date(a.ends):'No end date'}</small></td><td data-label="Access review">${date(a.reviewDue)}<small>Last reviewed ${date(a.reviewed)}</small></td>${actionable?`<td data-label="Actions"><div class="row wrap">${a.status==='Active'?btn('Review','gv-review-assignment',`data-id="${a.id}"`,'small'):''}${a.status==='Active'?btn('Revoke','gv-revoke-assignment',`data-id="${a.id}"`,'quiet small danger'):''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('No assignments','Grant this role to a person and a defined organization scope.');}
function gvAccessView(){gvInit();const st=gvState();const rows=st.assignments.filter(a=>!selectedScope()||gvOverlap(selectedScope(),a.scopeId));return header('People & access review','Review scoped assignments, time-limited exceptions and the exact reason an action is allowed or denied.',btn(icon('plus')+' Assign role','gv-assign-role','','primary'),'Access governance')+gvNav('access-review')+`<div class="gv-section-actions">${btn('Add direct rule','gv-direct-rule','','small')}${btn('Export access register','gv-export-access','','small')}${link('Audit history','access-review?tab=audit','small')}</div>`+(current.params.get('tab')==='audit'?gvAuditView():panel('Role assignments',`${rows.length} assignments intersect the selected scope. Expired assignments grant no access.`,gvAssignmentsTable(rows))+panel('Direct permission rules','Use an expiry and a reason. A direct deny overrides role grants.',st.directRules.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Person / permission</th><th>Scope & reason</th><th>Effect / expiry</th><th>Action</th></tr></thead><tbody>${st.directRules.filter(d=>!selectedScope()||gvOverlap(selectedScope(),d.scopeId)).map(d=>`<tr><td><strong>${e(gvPerson(d.userId)?.name)}</strong><small>${e(d.permission)}</small></td><td>${e(gvScope(d.scopeId))}<small>${e(d.reason)}</small></td><td>${pill(d.effect,d.effect==='deny'?'red':'green')}<small>${date(d.ends)} · ${gvActive(d)?'Active':'Inactive'}</small></td><td>${d.status==='Active'?btn('Revoke rule','gv-revoke-direct',`data-id="${d.id}"`,'quiet small danger'):pill('Revoked')}</td></tr>`).join('')}</tbody></table></div>`:empty('No direct rules','Prefer reusable roles; use direct rules for specific temporary exceptions.')))+gvAccessSimulator();}
function gvAuditView(){return panel('Access & escalation change history','Local receipts include the actor, reason and affected record. Production requires a server-protected audit log.',gvState().audit.length?`<ol class="timeline">${gvState().audit.map(a=>`<li><strong>${e(a.action)}</strong><p>${e(a.detail)}</p><small>${e(a.by)} · ${e(recTimestamp(a.at))} · ${e(a.ref)}</small></li>`).join('')}</ol>`:empty('No changes recorded','A saved role, assignment decision or escalation policy creates a receipt.'));}
function gvAccessSimulator(){const d=gvState().accessSimulation||{userId:'USR-01',permission:'kri.approve',scopeId:'U-IK-PAY',on:gvToday(),own:false};const result=gvDecision(d.userId,d.permission,d.scopeId,d.on,{makerId:d.own?d.userId:''});return `<section class="panel gv-simulator mt16"><div class="panel-head"><div><h2>Explain effective access</h2><p>Evaluate all active roles and direct rules for one person, action, date and location.</p></div>${pill(result.allowed?'Allowed':'Denied',result.allowed?'green':'red')}</div><form data-gv-form="simulate-access" class="pad"><div class="field-grid"><label>Person<select name="userId">${gvPeopleOptions(d.userId)}</select></label><label>Action<select name="permission">${GV_MODULES.flatMap(([m,label])=>GV_ACTIONS.map(([a,t])=>`<option value="${m}.${a}" ${d.permission===m+'.'+a?'selected':''}>${e(label+' · '+t)}</option>`)).join('')}</select></label><label>Record location<select name="scopeId">${gvScopeOptions(d.scopeId)}</select></label><label>Evaluate on<input type="date" name="on" required value="${d.on}"></label><label class="checkbox-row full"><input name="own" type="checkbox" ${d.own?'checked':''}>The person also prepared the submission being approved</label></div><div class="gv-card-actions"><button class="btn primary" type="submit">Explain decision</button></div><div class="form-error" role="alert"></div></form><div class="gv-access-result" role="status"><strong>${e(result.reason)}</strong>${result.trace.length?`<ul>${result.trace.map(t=>`<li>${pill(t.effect,t.effect==='deny'?'red':t.effect==='allow'?'green':'')} <span>${e(t.source)}<small>${e(t.scope)} · ${e(t.until)}</small></span></li>`).join('')}</ul>`:'<p>No matching active assignments or direct rules.</p>'}<small>Decision preview only. It does not impersonate the person or change your session.</small></div></section>`;}
function gvAssignDialog(){openDialog('Assign a scoped role','The person, role, dates and maximum scope are checked before assignment.',`<div class="field-grid"><label>Person<select name="userId">${gvPeopleOptions()}</select></label><label>Role<select name="roleId">${gvRoleOptions('ROLE-CONTRIBUTOR')}</select></label><label class="full">Assignment scope<select name="scopeId">${gvScopeOptions(selectedScope())}</select></label><label>Starts<input type="date" name="starts" value="${gvToday()}" required></label><label>Ends (optional)<input type="date" name="ends"></label><label class="full">Business reason<textarea name="reason" minlength="12" required></textarea></label></div>`,'Assign role',form=>{const v=values(form),r=gvRole(v.roleId);requireValue(r?.status==='Active'&&gvPerson(v.userId),'Choose an active role and known person.');validDate(v.starts,'Start date',false);if(v.ends){validDate(v.ends,'End date',false);requireValue(v.ends>=v.starts,'End date must not precede the start date.');}requireValue(v.scopeId===''||orgNode(v.scopeId),'Choose a valid assignment scope.');requireValue(gvCovers(r.scopeRoot,v.scopeId,r.descendants),'Assignment scope exceeds the role’s maximum scope.');requireValue(v.reason.trim().length>=12,'Give a specific business reason.');requireValue(!gvState().assignments.some(a=>a.userId===v.userId&&a.roleId===v.roleId&&a.scopeId===v.scopeId&&a.status==='Active'&&(!a.ends||a.ends>=v.starts)&&(!v.ends||v.ends>=a.starts)),'This person already has an overlapping assignment for this role and scope.');const a={...v,id:uid('GVA'),status:'Active',reviewed:gvToday(),reviewDue:addDays(v.starts,Number(r.reviewEvery))};const conflicts=gvConflictFor(a);requireValue(!conflicts.length,'Separation of duties conflict. '+conflicts.join(' '));gvState().assignments.push(a);gvAudit('Assigned '+r.name,a.id,v.reason+' · '+gvPerson(v.userId).name+' · '+gvScope(v.scopeId));render();toast('Role assigned within the selected scope and validity dates.');});}
function gvKeepAdmin(removedId){const others=gvState().assignments.filter(a=>a.id!==removedId&&a.roleId==='ROLE-ADMIN'&&a.scopeId===''&&gvActive(a));requireValue(others.length,'Keep at least one active organization-wide workspace administrator before revoking this assignment.');}
function gvAssignmentDialog(id,revoke=false){const a=gvState().assignments.find(a=>a.id===id);requireValue(a,'Assignment not found.');if(revoke&&a.roleId==='ROLE-ADMIN')gvKeepAdmin(id);openDialog(revoke?'Revoke role assignment':'Review role assignment',gvPerson(a.userId).name+' · '+gvRole(a.roleId).name,`<p>Scope: <strong>${e(gvScope(a.scopeId))}</strong>. ${e(a.reason)}</p>${!revoke?`<label>Decision<select name="decision"><option value="retain">Retain access</option><option value="revoke">Revoke access</option></select></label><label class="mt16">Next review date<input name="reviewDue" type="date" value="${addDays(gvToday(),Number(gvRole(a.roleId).reviewEvery))}" required></label>`:''}<label class="mt16">Decision rationale<textarea name="reason" minlength="12" required></textarea></label>`,'Record decision',form=>{const v=values(form);requireValue(v.reason.trim().length>=12,'Record the reason for this access decision.');const remove=revoke||v.decision==='revoke';if(remove){if(a.roleId==='ROLE-ADMIN')gvKeepAdmin(a.id);a.status='Revoked';a.revokedAt=gvClock();}else{requireValue(!a.ends||a.ends>=gvToday(),'This assignment has expired. Create a new dated assignment to restore access.');validDate(v.reviewDue,'Next review',false);requireValue(v.reviewDue>gvToday(),'The next review must be after the current demonstration date.');a.reviewed=gvToday();a.reviewDue=v.reviewDue;}gvAudit(remove?'Revoked role assignment':'Recertified role assignment',a.id,v.reason);render();toast('Access decision recorded.');});}
function gvDirectDialog(){openDialog('Add a direct permission rule','Time-limited rules need an independent reviewer and a business reason.',`<div class="field-grid"><label>Person<select name="userId">${gvPeopleOptions('USR-01')}</select></label><label>Effect<select name="effect"><option value="deny">Deny</option><option value="allow">Allow</option></select></label><label class="full">Action<select name="permission">${GV_MODULES.filter(x=>x[0]!=='access').flatMap(([m,label])=>GV_ACTIONS.map(([a,t])=>`<option value="${m}.${a}">${e(label+' · '+t)}</option>`)).join('')}</select></label><label class="full">Scope<select name="scopeId">${gvScopeOptions(selectedScope())}</select></label><label>Valid from<input type="date" name="starts" value="${gvToday()}" required></label><label>Expires<input type="date" name="ends" value="${addDays(gvToday(),30)}" required></label><label>Reviewed by<select name="approvedBy">${gvPeopleOptions('USR-05')}</select></label><label class="full">Reason<textarea name="reason" minlength="12" required></textarea></label></div>`,'Record direct rule',form=>{const v=values(form);requireValue(gvPerson(v.userId)&&gvPerson(v.approvedBy)&&(v.scopeId===''||orgNode(v.scopeId)),'Choose a known person, reviewer and scope.');requireValue(v.userId!==v.approvedBy,'The person receiving the rule cannot independently approve it.');requireValue(gvDecision(v.approvedBy,'access.manage','').allowed,'The reviewer must have organization-wide access-management permission.');validDate(v.starts,'Start date',false);validDate(v.ends,'Expiry date',false);requireValue(v.ends>=v.starts&&days(v.ends,v.starts)<=90,'Direct rules must expire within 90 days of their start date.');requireValue(v.reason.trim().length>=12,'Give a specific reason for this exception.');if(v.effect==='allow'){const mod=v.permission.split('.')[0],action=v.permission.split('.')[1];const conflictActions=action==='approve'?['edit','submit']:['edit','submit'].includes(action)?['approve']:[];const covered=['',...ORG.map(n=>n.id)].filter(id=>gvCovers(v.scopeId,id));const dates=[v.starts,...gvState().assignments.filter(a=>a.userId===v.userId&&a.status==='Active'&&a.starts>=v.starts&&a.starts<=v.ends).map(a=>a.starts)];requireValue(!conflictActions.some(a=>covered.some(scope=>dates.some(on=>gvDecision(v.userId,mod+'.'+a,scope,on).allowed))),'This direct grant conflicts with preparation / approval separation in the selected scope.');}gvState().directRules.push({...v,id:uid('GVD'),status:'Active'});gvAudit('Added '+v.effect+' rule',v.permission,v.reason+' · '+gvPerson(v.userId).name);render();toast('Direct rule recorded with expiry and reviewer.');});}
function gvMatchPolicy(trigger,severity,scopeId){const rank=GV_SEVERITIES.indexOf(severity);if(rank<1||!GV_TRIGGERS.some(x=>x[0]===trigger)||!orgNode(scopeId))return null;const candidates=gvState().policies.filter(p=>p.status==='Active'&&p.trigger===trigger&&gvCovers(p.scopeId,scopeId)&&rank>=GV_SEVERITIES.indexOf(p.severity));candidates.sort((a,b)=>(b.scopeId?orgPath(b.scopeId).length:0)-(a.scopeId?orgPath(a.scopeId).length:0)||GV_SEVERITIES.indexOf(b.severity)-GV_SEVERITIES.indexOf(a.severity)||a.id.localeCompare(b.id));return candidates[0]||null;}
function gvPolicyName(trigger){return GV_TRIGGERS.find(x=>x[0]===trigger)?.[1]||trigger;}
function gvTargetLabel(id){return id==='owner'?'Record owner':gvRole(id)?.name||'Unassigned role';}
function gvMatrixView(){gvInit();const policies=gvState().policies.filter(p=>!selectedScope()||gvOverlap(p.scopeId,selectedScope()));return header('Escalation matrix','Connect risk signals and overdue work to accountable people, timed follow-ups and a clear stopping condition.',btn(icon('plus')+' Create policy','gv-new-policy','','primary'),'Accountability & response')+gvNav('escalation-matrix')+`<div class="gv-escalation-summary"><div><span class="eyebrow">Response model</span><h2>Owner → independent review → executive attention</h2><p>Each level is measured from the original trigger. Missing recipients use a named fallback, and unresolved routing remains visible.</p></div><div class="gv-summary-chips">${pill(policies.filter(p=>p.status==='Active').length+' active policies','blue')}${pill('Africa/Lagos · WAT')}${pill('No external messages')}</div></div>`+panel('Configured response policies','A policy matches the event type, severity threshold and organizational scope.',`<div class="table-wrap"><table class="table"><thead><tr><th>Policy / signal</th><th>Scope</th><th>Escalation levels</th><th>Clock / stop</th><th>Action</th></tr></thead><tbody>${policies.map(p=>`<tr><td><strong>${e(p.name)}</strong><small>${e(gvPolicyName(p.trigger))} · ${e(p.severity)} severity</small>${pill(p.status)}</td><td>${e(gvScope(p.scopeId))}</td><td><div class="gv-level-chips">${p.levels.map((l,i)=>`<span><b>L${i+1} · ${l.after===0?'Immediately':l.after+'h'}</b>${e(gvTargetLabel(l.target))}</span>`).join('')}</div></td><td>${p.clock==='business'?'Business hours':'Calendar hours'}<small>Stop: ${p.stop==='acknowledged'?'acknowledged or resolved':'resolved'}</small></td><td><div class="row wrap">${link('Configure','escalation-policy?id='+p.id,'small')}${btn('Simulate','gv-select-policy',`data-id="${p.id}"`,'quiet small')}</div></td></tr>`).join('')}</tbody></table></div>`)+gvEscalationSimulator();}
function gvPolicyDraft(id){if(gvState().draftPolicy?.sourceId===id)return gvState().draftPolicy;const p=gvState().policies.find(p=>p.id===id);if(!p)return null;gvState().draftPolicy={...clone(p),sourceId:id,reason:''};save();return gvState().draftPolicy;}
function gvPolicyDetail(){gvInit();const id=current.params.get('id'),p=id==='new'?gvState().draftPolicy:gvPolicyDraft(id);if(!p||p.sourceId!==id)return header('Escalation policy not found','Choose a policy from the escalation matrix.',link('Escalation matrix','escalation-matrix'));return header(e(p.name||'New escalation policy'),'Set the signal, response clock, recipients and fallback for every escalation level.',link('Back to matrix','escalation-matrix')+btn('Save policy','gv-save-policy','','primary'),'Escalation policy')+gvNav('escalation-matrix')+`<div id="gv-policy-error" class="form-error" role="alert"></div><section class="panel pad"><div class="field-grid"><label>Name<input data-gv-policy="name" value="${e(p.name)}" maxlength="100"></label><label>Status<select data-gv-policy="status">${['Active','Inactive'].map(v=>`<option ${p.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Trigger<select data-gv-policy="trigger">${GV_TRIGGERS.map(([v,t])=>`<option value="${v}" ${p.trigger===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Minimum severity<select data-gv-policy="severity">${GV_SEVERITIES.map(v=>`<option ${p.severity===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Organizational scope<select data-gv-policy="scopeId">${gvScopeOptions(p.scopeId)}</select></label><label>Policy owner<select data-gv-policy="owner">${gvPeopleOptions(p.owner)}</select></label><label>Response clock<select data-gv-policy="clock"><option value="calendar" ${p.clock==='calendar'?'selected':''}>Calendar hours · 24/7</option><option value="business" ${p.clock==='business'?'selected':''}>Business hours · Mon–Fri, 08:00–17:00 WAT</option></select></label><label>Stop future escalation when<select data-gv-policy="stop"><option value="resolved" ${p.stop==='resolved'?'selected':''}>The source issue is resolved</option><option value="acknowledged" ${p.stop==='acknowledged'?'selected':''}>Acknowledged or resolved</option></select></label></div></section><section class="panel pad mt16"><div class="row between wrap"><div><h2>Timed escalation levels</h2><p>Delays are cumulative from the original trigger. Each level sends once; there is no repeated reminder storm.</p></div>${btn('Add level','gv-add-level','','small')}</div><div class="gv-level-editor">${p.levels.map((l,i)=>`<div class="gv-level-row"><div class="gv-level-number">${i+1}</div><label>After hours<input type="number" min="0" max="720" step="1" data-gv-level="${i}" data-gv-field="after" value="${l.after}"></label><label>Notify<select data-gv-level="${i}" data-gv-field="target">${gvRoleOptions(l.target,true)}</select></label><label>If unassigned, notify<select data-gv-level="${i}" data-gv-field="fallback">${gvRoleOptions(l.fallback)}</select></label>${btn(icon('close'),'gv-remove-level',`data-index="${i}" aria-label="Remove escalation level ${i+1}" ${p.levels.length===1?'disabled':''}`,'quiet icon-only')}</div>`).join('')}</div></section><section class="panel pad mt16"><h2>Before saving</h2><p>Recipients are resolved from active assignments at the incident location. Escalation does not grant access to the underlying record. Business time excludes weekends; no holiday calendar is configured in this demonstration.</p><label>Reason for policy change<textarea data-gv-policy="reason">${e(p.reason||'')}</textarea></label><div class="gv-card-actions">${btn('Discard changes','gv-discard-policy','','quiet')}${btn('Save policy','gv-save-policy','','primary')}</div></section>`;}
function gvSavePolicy(){const d=gvState().draftPolicy;requireValue(d,'Policy draft unavailable.');requireValue(d.name.trim().length>=3&&d.reason.trim().length>=12,'Provide a policy name and a specific change reason.');requireValue(GV_TRIGGERS.some(x=>x[0]===d.trigger)&&GV_SEVERITIES.includes(d.severity),'Choose a known trigger and severity.');requireValue(gvPerson(d.owner)&&(d.scopeId===''||orgNode(d.scopeId)),'Choose a policy owner and a valid scope.');requireValue(d.levels.length>=1&&d.levels.length<=6,'Use between one and six escalation levels.');let prev=-1;for(const l of d.levels){const n=bounded(l.after,0,720,'Escalation delay');requireValue(n>prev,'Each escalation delay must be later than the previous level, measured from the original trigger.');prev=n;requireValue(l.target==='owner'||gvRole(l.target)?.status==='Active','Every level needs an active recipient role or the record owner.');requireValue(gvRole(l.fallback)?.status==='Active','Every level needs an active fallback role.');requireValue(l.target!==l.fallback,'Choose a different fallback role from the primary recipient.');}const same=gvState().policies.find(p=>p.id!==d.sourceId&&p.status==='Active'&&d.status==='Active'&&p.trigger===d.trigger&&p.scopeId===d.scopeId&&p.severity===d.severity);requireValue(!same,'An active policy already uses this trigger, scope and severity. Edit it or use a different scope.');const p={...clone(d),id:d.sourceId==='new'?uid('ESC'):d.sourceId,name:d.name.trim(),levels:d.levels.map(l=>({...l,after:Number(l.after)})),version:(d.version||0)+1,updated:gvToday()};delete p.reason;delete p.sourceId;const idx=gvState().policies.findIndex(x=>x.id===p.id);if(idx<0)gvState().policies.push(p);else gvState().policies[idx]=p;gvState().draftPolicy=null;gvState().simulation=null;gvAudit('Saved escalation policy',p.id,d.reason+' · version '+p.version);go('escalation-matrix');toast('Escalation policy saved. Run a simulation to inspect routing and timing.');}
function gvBusinessTime(start,hours){let t=new Date(start),remaining=hours*3600000;for(let guard=0;guard<800;guard++){const local=new Date(t.getTime()+3600000),day=local.getUTCDay(),datePart=local.toISOString().slice(0,10),open=new Date(datePart+'T08:00:00+01:00'),close=new Date(datePart+'T17:00:00+01:00');if(day===0||day===6||t>=close){t=new Date(new Date(datePart+'T00:00:00Z').getTime()+86400000+7*3600000);continue;}if(t<open)t=open;if(remaining===0)return t;const available=close-t;if(remaining<=available)return new Date(+t+remaining);remaining-=available;t=new Date(+close+1);}throw new Error('Business calendar calculation exceeded its range.');}
function gvRecipients(target,scopeId,ownerId,on){if(target==='owner')return gvPerson(ownerId)?[gvPerson(ownerId)]:[];const role=gvRole(target);if(!role||role.status!=='Active'||!gvCovers(role.scopeRoot,scopeId,role.descendants))return [];return [...new Set(gvState().assignments.filter(a=>a.roleId===target&&gvActive(a,on)&&gvCovers(a.scopeId,scopeId)).map(a=>a.userId))].map(gvPerson).filter(Boolean);}
function gvSimulate(v){const p=gvState().policies.find(p=>p.id===v.policyId);requireValue(p&&p.status==='Active','Choose an active escalation policy.');requireValue(orgNode(v.scopeId),'Select a specific event location.');requireValue(gvCovers(p.scopeId,v.scopeId),'This policy does not cover the selected event location.');const rank=GV_SEVERITIES.indexOf(v.severity);requireValue(rank>=GV_SEVERITIES.indexOf(p.severity),'This event severity is below the policy’s minimum severity.');const start=new Date(v.at+':00+01:00');requireValue(!Number.isNaN(+start),'Choose a valid trigger time in WAT.');for(const key of ['ackAfter','resolvedAfter'])if(v[key]!=='')requireValue(Number.isFinite(Number(v[key]))&&Number(v[key])>=0&&Number(v[key])<=1000,'Acknowledgement and resolution delays must be between 0 and 1,000 calendar hours.');const ack=v.ackAfter===''?null:new Date(+start+Number(v.ackAfter)*3600000),resolved=v.resolvedAfter===''?null:new Date(+start+Number(v.resolvedAfter)*3600000);const levels=p.levels.map((l,i)=>{const due=p.clock==='business'?gvBusinessTime(start,Number(l.after)):new Date(+start+Number(l.after)*3600000);let status='Scheduled',reason='';if(resolved&&due>=resolved){status='Stopped';reason='Issue resolved before this level.';}else if(p.stop==='acknowledged'&&ack&&due>=ack){status='Stopped';reason='Acknowledged before this level.';}const on=new Date(+due+3600000).toISOString().slice(0,10),primary=gvRecipients(l.target,v.scopeId,v.ownerId,on),fallback=!primary.length,recipients=primary.length?primary:gvRecipients(l.fallback,v.scopeId,v.ownerId,on);if(!recipients.length&&status!=='Stopped'){status='Unassigned';reason='No active primary or fallback assignment covers this location. The policy owner must resolve routing.';}return {level:i+1,due:due.toISOString(),after:l.after,target:l.target,fallback:fallback?l.fallback:null,recipients:recipients.map(x=>({id:x.id,name:x.name})),status,reason};});return {policyId:p.id,policyName:p.name,policyVersion:p.version,scopeId:v.scopeId,at:start.toISOString(),clock:p.clock,stop:p.stop,levels,owner:gvPerson(p.owner)?.name};}
function gvEscalationSimulator(){const st=gvState(),d=st.simulator,result=st.simulation;return `<section class="panel mt16 gv-simulator" id="gv-escalation-simulator"><div class="panel-head"><div><h2>Test a real response path</h2><p>Preview due times, actual role holders, fallback routing and stop conditions before relying on the policy.</p></div>${pill('Simulation','blue')}</div><form data-gv-form="simulate-escalation" class="pad"><div class="field-grid"><label>Policy<select name="policyId">${st.policies.filter(p=>p.status==='Active').map(p=>`<option value="${p.id}" ${d.policyId===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><label>Event severity<select name="severity">${GV_SEVERITIES.filter(x=>x!=='Any').map(v=>`<option ${v===d.severity?'selected':''}>${v}</option>`).join('')}</select></label><label>Event location<select name="scopeId">${gvScopeOptions(d.scopeId,false)}</select></label><label>Record owner<select name="ownerId">${gvPeopleOptions(d.ownerId,true)}</select></label><label>Triggered at (WAT)<input type="datetime-local" name="at" required value="${d.at}"></label><label>Acknowledged after calendar hours (optional)<input type="number" min="0" max="1000" step="0.5" name="ackAfter" value="${d.ackAfter}" placeholder="Leave blank: unacknowledged"></label><label>Resolved after calendar hours (optional)<input type="number" min="0" max="1000" step="0.5" name="resolvedAfter" value="${d.resolvedAfter}" placeholder="Leave blank: unresolved"></label></div><div class="gv-card-actions"><button type="submit" class="btn primary">Run simulation</button>${result?btn('Export simulation','gv-export-simulation','','small'):''}</div><div class="form-error" role="alert"></div></form>${result?gvSimulationResult(result):'<div class="gv-sim-empty"><span class="gv-role-icon">'+icon('clock')+'</span><p>Run the simulation to see who will receive each escalation and exactly when.</p></div>'}</section>`;}
function gvSimulationResult(result){return `<div class="gv-sim-result" role="status"><div class="row between wrap"><div><h3>${e(result.policyName)} · version ${result.policyVersion}</h3><p>${e(gvScope(result.scopeId))} · ${result.clock==='business'?'Business':'Calendar'} hours · policy owner: ${e(result.owner)}</p></div>${pill(result.levels.some(l=>l.status==='Unassigned')?'Routing needs attention':'Routing resolved',result.levels.some(l=>l.status==='Unassigned')?'red':'green')}</div><ol class="gv-response-timeline">${result.levels.map(l=>`<li class="gv-response-${l.status.toLowerCase()}"><div class="gv-level-number">${l.level}</div><div><div class="row between wrap"><strong>${e(recTimestamp(l.due))}</strong>${pill(l.status,l.status==='Unassigned'?'red':l.status==='Stopped'?'':'blue')}</div><p>${l.status==='Stopped'?e(l.reason):l.recipients.length?e(l.recipients.map(r=>r.name).join(', ')):e(l.reason)}</p><small>${e(gvTargetLabel(l.target))}${l.fallback?' → fallback: '+e(gvTargetLabel(l.fallback)):''} · ${l.after===0?'immediate':l.after+' hours from trigger'}</small></div></li>`).join('')}</ol><p class="small mb0">This preview sends no notifications. Production delivery must use an idempotent queue, role resolution at send time and the current source status.</p></div>`;}
function gvError(id,err){const el=$(id);if(el){el.textContent=err.message;el.scrollIntoView({block:'center'});}else toast(err.message);}
Object.assign(actions,{
 'gv-new-role':()=>gvNewRole(), 'gv-clone-role':el=>gvNewRole(el.dataset.id),
 'gv-save-role':()=>{try{gvSaveRole();}catch(err){gvError('#gv-role-error',err);}},
 'gv-discard-role':()=>{gvState().draftRole=null;save();go('roles');},
 'gv-assign-role':gvAssignDialog,'gv-review-assignment':el=>gvAssignmentDialog(el.dataset.id), 'gv-revoke-assignment':el=>gvAssignmentDialog(el.dataset.id,true),
 'gv-direct-rule':gvDirectDialog,
 'gv-revoke-direct':el=>{const d=gvState().directRules.find(x=>x.id===el.dataset.id);requireValue(d,'Rule not found.');openDialog('Revoke direct rule',gvPerson(d.userId).name+' · '+d.permission,'<label>Reason<textarea name="reason" minlength="12" required></textarea></label>','Revoke rule',form=>{const v=values(form);requireValue(v.reason.trim().length>=12,'Record a reason for revocation.');d.status='Revoked';gvAudit('Revoked direct rule',d.id,v.reason);render();});},
 'gv-export-access':()=>download('clearsight-access-register.json',JSON.stringify({synthetic:true,evaluatedAt:gvToday(),scope:clone(S.scope),roles:clone(gvState().roles),assignments:gvState().assignments.filter(a=>!selectedScope()||gvOverlap(selectedScope(),a.scopeId)),directRules:gvState().directRules.filter(d=>!selectedScope()||gvOverlap(selectedScope(),d.scopeId)),audit:gvState().audit},null,2)),
 'gv-new-policy':()=>{gvState().draftPolicy={id:'new',sourceId:'new',name:'',trigger:'deadline-approaching',severity:'Any',scopeId:selectedScope(),status:'Active',clock:'business',stop:'resolved',owner:'USR-03',version:0,levels:[{after:0,target:'owner',fallback:'ROLE-REVIEWER'},{after:8,target:'ROLE-REVIEWER',fallback:'ROLE-CRO'}],reason:''};save();go('escalation-policy?id=new');},
 'gv-save-policy':()=>{try{gvSavePolicy();}catch(err){gvError('#gv-policy-error',err);}},
 'gv-discard-policy':()=>{gvState().draftPolicy=null;save();go('escalation-matrix');},
 'gv-add-level':()=>{const d=gvState().draftPolicy;requireValue(d&&d.levels.length<6,'Use at most six escalation levels.');d.levels.push({after:Number(d.levels.at(-1)?.after||0)+8,target:'ROLE-CRO',fallback:'ROLE-ADMIN'});save();render();},
 'gv-remove-level':el=>{const d=gvState().draftPolicy;requireValue(d&&d.levels.length>1,'Keep at least one escalation level.');d.levels.splice(Number(el.dataset.index),1);save();render();},
 'gv-select-policy':el=>{gvState().simulator.policyId=el.dataset.id;gvState().simulation=null;save();render();$('#gv-escalation-simulator')?.scrollIntoView({block:'start'});},
 'gv-export-simulation':()=>{requireValue(gvState().simulation,'Run a simulation first.');download('clearsight-escalation-simulation.json',JSON.stringify({synthetic:true,deliveryPerformed:false,...gvState().simulation},null,2));}
});
document.addEventListener('input',ev=>{const el=ev.target;if(el.matches('[data-gv-role]')){const d=gvState()?.draftRole;if(!d||d.system)return;d[el.dataset.gvRole]=el.type==='checkbox'?el.checked:el.value;save();}if(el.matches('[data-gv-policy]')){const d=gvState()?.draftPolicy;if(!d)return;d[el.dataset.gvPolicy]=el.value;save();}if(el.matches('[data-gv-level]')){const d=gvState()?.draftPolicy;if(!d)return;d.levels[Number(el.dataset.gvLevel)][el.dataset.gvField]=el.value;save();}});
document.addEventListener('change',ev=>{const el=ev.target;if(el.matches('[data-gv-permission]')){const d=gvState()?.draftRole;if(!d||d.system)return;if(el.value==='unset')delete d.permissions[el.dataset.gvPermission];else d.permissions[el.dataset.gvPermission]=el.value;el.className='gv-effect gv-effect-'+el.value;$('#gv-sod-preview').innerHTML=gvSodMarkup(d);save();}if(el.matches('[data-gv-role],[data-gv-policy],[data-gv-level]'))el.dispatchEvent(new Event('input',{bubbles:true}));});
document.addEventListener('submit',ev=>{const form=ev.target;if(!form.matches('[data-gv-form]'))return;ev.preventDefault();try{const v=values(form);if(form.dataset.gvForm==='simulate-access'){validDate(v.on,'Evaluation date',false);gvState().accessSimulation={...v,own:v.own==='on'};save();render();$('.gv-access-result')?.scrollIntoView({block:'center'});}if(form.dataset.gvForm==='simulate-escalation'){const result=gvSimulate(v);gvState().simulator=v;gvState().simulation=result;save();render();$('.gv-sim-result')?.scrollIntoView({block:'start'});}}catch(err){const error=$('.form-error',form);error.textContent=err.message;error.scrollIntoView({block:'center'});}});
Object.assign(window.CS_JOURNEYS,{'roles':gvRolesView,'role-detail':gvRoleDetail,'access-review':gvAccessView,'escalation-matrix':gvMatrixView,'escalation-policy':gvPolicyDetail});
Object.assign(window.CS_JOURNEY_GROUPS,{'roles':'settings','role-detail':'settings','access-review':'settings','escalation-matrix':'settings','escalation-policy':'settings'});
Object.assign(titles,{'roles':'Roles & permissions','role-detail':'Role configuration','access-review':'People & access review','escalation-matrix':'Escalation matrix','escalation-policy':'Escalation policy'});
const gvPreviousSettings=settingsView;
settingsView=function(){return `<div class="gv-settings-entry panel pad"><div><span class="eyebrow">Workspace administration</span><h2>Access, accountability and response</h2><p class="mb0">Set scoped roles, review access and define escalation ownership.</p></div><div class="row wrap">${link('Roles & permissions','roles','primary')}${link('Escalation matrix','escalation-matrix')}</div></div>`+gvPreviousSettings();};
const gvPreviousRender=render;
render=function(){gvInit();gvPreviousRender();};
window.CLEAR_SIGHT_GOVERNANCE=Object.freeze({version:'2.8-design-preview',getState:()=>clone(gvState()),evaluate:(userId,permission,scopeId,on,context)=>clone(gvDecision(userId,permission,scopeId,on,context)),simulate:values=>clone(gvSimulate(values)),matchPolicy:(trigger,severity,scopeId)=>clone(gvMatchPolicy(trigger,severity,scopeId)),businessTime:(start,hours)=>gvBusinessTime(new Date(start),hours).toISOString(),conflicts:assignment=>clone(gvConflictFor(assignment))});
